package com.hunter.btc

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Test

/** Vectores generados con la implementación de referencia (argon2-cffi y hashlib.blake2b de Python). */
class Argon2idTest {
    private fun h(s: String) = if (s == "-") ByteArray(0) else ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

    @Test fun blake2bContraLaReferencia() {
        for (c in BLAKE) {
            val b = Argon2id.Blake2b(c[0].toInt()); b.update(h(c[1]))
            assertEquals("len=${c[0]} data=${c[1].take(16)}", c[2], hex(b.digest()))
        }
    }

    @Test fun argon2idContraLaReferencia() {
        for (c in ARGON) {
            val clave = Argon2id.derivar(h(c[0]), h(c[1]), c[2].toInt(), c[3].toInt(), c[4].toInt(), c[5].toInt())
            assertEquals("t=${c[2]} m=${c[3]} p=${c[4]}", c[6], hex(clave))
        }
    }

    @Test fun cambiarUnParametroCambiaLaClave() {
        val a = Argon2id.derivar("pw".toByteArray(), "saltsalt".toByteArray(), 2, 64, 1, 32)
        assertFalse(a.contentEquals(Argon2id.derivar("pw".toByteArray(), "saltsalt".toByteArray(), 3, 64, 1, 32)))
        assertFalse(a.contentEquals(Argon2id.derivar("pw".toByteArray(), "saltsalU".toByteArray(), 2, 64, 1, 32)))
        assertArrayEquals(a, Argon2id.derivar("pw".toByteArray(), "saltsalt".toByteArray(), 2, 64, 1, 32))
    }

